questions.sparql:
SELECT ?o ?building ?height ?shadow WHERE {
  c:Sun twin:shadowPerMetre ?k . c:Park twin:depictedBy ?pk .
  ?b twin:permitHeightM ?ph ; twin:depictedBy ?o ; rdfs:label ?building .
  { SELECT ?o ?ox ?oz WHERE { ?o x3do:translation ?oL . ?oL rdf:first ?ox . ?oL rdf:rest ?oR . ?oR rdf:rest ?oR2 . ?oR2 rdf:first ?oz . } } { SELECT ?o ?osx ?osy ?osz WHERE { ?o x3do:hasChildren ?oH . ?oH x3do:hasGeometry ?oB . ?oB x3do:size ?oS . ?oS rdf:first ?osx . ?oS rdf:rest ?oSR . ?oSR rdf:first ?osy . ?oSR rdf:rest ?oSR2 . ?oSR2 rdf:first ?osz . } } { SELECT ?pk ?pkx ?pkz WHERE { ?pk x3do:translation ?pkL . ?pkL rdf:first ?pkx . ?pkL rdf:rest ?pkR . ?pkR rdf:rest ?pkR2 . ?pkR2 rdf:first ?pkz . } } { SELECT ?pk ?pksx ?pksy ?pksz WHERE { ?pk x3do:hasChildren ?pkH . ?pkH x3do:hasGeometry ?pkB . ?pkB x3do:size ?pkS . ?pkS rdf:first ?pksx . ?pkS rdf:rest ?pkSR . ?pkSR rdf:first ?pksy . ?pkSR rdf:rest ?pkSR2 . ?pkSR2 rdf:first ?pksz . } }
  BIND(?osy AS ?height) BIND(?height * ?k AS ?shadow)
  FILTER(?oz - ?osz / 2 - ?shadow < ?pkz + ?pksz / 2 && ?oz - ?osz / 2 > ?pkz - ?pksz / 2)
  FILTER(ABS(?ox - ?pkx) < (?osx + ?pksx) / 2)
} ORDER BY ?building

SELECT ?o ?building WHERE {
  c:Flood twin:depictedBy ?fz . ?b twin:permitHeightM ?h ; twin:depictedBy ?o ; rdfs:label ?building .
  { SELECT ?o ?ox ?oz WHERE { ?o x3do:translation ?oL . ?oL rdf:first ?ox . ?oL rdf:rest ?oR . ?oR rdf:rest ?oR2 . ?oR2 rdf:first ?oz . } } { SELECT ?fz ?fzx ?fzz WHERE { ?fz x3do:translation ?fzL . ?fzL rdf:first ?fzx . ?fzL rdf:rest ?fzR . ?fzR rdf:rest ?fzR2 . ?fzR2 rdf:first ?fzz . } } { SELECT ?fz ?fzsx ?fzsy ?fzsz WHERE { ?fz x3do:hasChildren ?fzH . ?fzH x3do:hasGeometry ?fzB . ?fzB x3do:size ?fzS . ?fzS rdf:first ?fzsx . ?fzS rdf:rest ?fzSR . ?fzSR rdf:first ?fzsy . ?fzSR rdf:rest ?fzSR2 . ?fzSR2 rdf:first ?fzsz . } }
  FILTER(ABS(?ox - ?fzx) < ?fzsx / 2 && ABS(?oz - ?fzz) < ?fzsz / 2)
} ORDER BY ?building

SELECT ?o ?building WHERE {
  c:Stop twin:depictedBy ?st ; twin:walkRadiusM ?r . ?b twin:permitHeightM ?h ; twin:depictedBy ?o ; rdfs:label ?building .
  { SELECT ?o ?ox ?oz WHERE { ?o x3do:translation ?oL . ?oL rdf:first ?ox . ?oL rdf:rest ?oR . ?oR rdf:rest ?oR2 . ?oR2 rdf:first ?oz . } } { SELECT ?st ?stx ?stz WHERE { ?st x3do:translation ?stL . ?stL rdf:first ?stx . ?stL rdf:rest ?stR . ?stR rdf:rest ?stR2 . ?stR2 rdf:first ?stz . } }
  BIND((?ox - ?stx) * (?ox - ?stx) + (?oz - ?stz) * (?oz - ?stz) AS ?d2)
  FILTER(?d2 <= ?r * ?r)
} ORDER BY ?building

